// ❌ VIOLA OCP — cada nuevo enemigo requiere modificar este método
public void Attack(Enemy enemy)
{
    if (enemy is Goblin)
        DealSlashDamage();
    else if (enemy is Orc)
        DealSmashDamage();
    else if (enemy is Dragon)  // <-- MODIFICACIÓN para agregar Dragon
        DealFireDamage();
}

// ✅ RESPETA OCP — polimorfismo: agregar Dragon no modifica nada existente
public abstract class Enemy
{
    public abstract void Attack();
}
public class Goblin : Enemy { public override void Attack() => DealSlash(); }
public class Orc    : Enemy { public override void Attack() => DealSmash(); }
public class Dragon : Enemy { public override void Attack() => DealFire(); } // solo se agrega

// ❌ VIOLA LSP — FlyingEnemy rompe el contrato de MoveOnGround()
public class Enemy
{
    public virtual void MoveOnGround() { /* mueve por tierra */ }
}
public class FlyingEnemy : Enemy
{
    public override void MoveOnGround()
    {
        throw new System.NotImplementedException(); // ← VIOLA LSP
    }
}

// ✅ RESPETA LSP — jerarquía correcta con contratos propios
public abstract class Enemy        { public abstract void Move(); }
public class GroundEnemy : Enemy   { public override void Move() => MoveOnGround(); }
public class FlyingEnemy : Enemy   { public override void Move() => Fly(); }

