}

public class Enemy
{
    public virtual void MoveOnGround()
    {
        transform.Translate(direction * speed);
    }
}
public class FlyingEnemy : Enemy
{
    public override void MoveOnGround()
    {
        throw new System.NotImplementedException();
    }
}

public class CombatSystem : MonoBehaviour
{
    public void ExecuteAttacks(List<Enemy> enemies)
    {
        foreach (Enemy e in enemies)
        {
            e.Attack(); // sin if, sin cast
        }
    }
}

public class Rectangle
{
    public virtual float Width  { get; set; }
    public virtual float Height { get; set; }
    public float Area() => Width * Height;
}
public class Square : Rectangle
{
    public override float Width
    {
        set { base.Width = value; base.Height = value; }
    }
    public override float Height
    {
        set { base.Width = value; base.Height = value; }
    }
}

public abstract class Weapon
{
    public abstract void Fire();
    public abstract void Reload();
}
public class Sword : Weapon
{
    public override void Fire()   { throw new NotImplementedException(); }
    public override void Reload() { throw new NotImplementedException(); }
    public void Slash() { ... }
}

